	          + "|0[Xx][0-9A-Fa-f](?:'?[0-9A-Fa-f])*" // Hexadecimal.
	          + "|0(?:'?[0-7])*" // Octal or just a lone zero.
	          + "|[1-9](?:'?[0-9])*" // Decimal.
	        + ")(?:" // Literal suffixes.
	          + "[Uu](?:LL?|ll?)"
	          + "|[Uu][Zz]?"
	          + "|(?:LL?|ll?)[Uu]?"
