	    // ihttps://www.postgresql.org/docs/devel/static/lo-funcs.html
	    + 'LO_FROM_BYTEA LO_PUT LO_GET LO_CREAT LO_CREATE LO_UNLINK LO_IMPORT LO_EXPORT LOREAD LOWRITE '
